ch3.starterCode:
# Weather is already set
# hewa is "mvua" or "jua"

# Choose the right path!
kama (hewa ni "mvua") {
  acha njia = "pango"
} la sivyo {
  acha njia = "mto"
}

andika(njia)

ch4.starterCode:
# Cross the bridge in 5 steps

acha hatua = 0

rudia (acha i = 0; i chini 5; i++) {
  hatua = hatua + 1
}

andika(hatua)

ch5.starterCode:
# Create a double function

kazi maraMbili(nambari) {
  rudisha nambari * 2
}

acha jibu = maraMbili(7)
andika(jibu)
